-- Data of HL7DocumentDaoTest (H2, Oracle mode): raw and standardized HL7 messages of CCD document 100, their segment
-- tables, the CCD documents and MPI changes the loader's status updates read.

CREATE ALIAS FN_TO_DATE FOR "gov.ny.state.doh.bhae.nyehms.web.spring.dao.document.HL7DocumentDaoTest.fnToDate";
CREATE ALIAS TO_CLOB FOR "gov.ny.state.doh.bhae.nyehms.web.spring.dao.document.HL7DocumentDaoTest.toClob";

CREATE TABLE RAW_HL7_DOC (DOCUMENT_ID NUMBER, CURRENT_PROCESS_STATUS NUMBER, MSHSENDINGFACILITYCODE VARCHAR2(100), MSHSENDINGFACILITYNAME VARCHAR2(200), NYC_SHIP_DATE DATE,
    PIDADDRESSLINE1 VARCHAR2(200), PIDADDRESSLINE2 VARCHAR2(200), PIDCITY VARCHAR2(100), PIDCOUNTRYCODE VARCHAR2(50), PIDCOUNTRYOFORIGIN VARCHAR2(50), PIDDATEOFBIRTHRAW VARCHAR2(50),
    PIDDIN VARCHAR2(50), PIDETHNICGROUPCODE VARCHAR2(50), PIDFACILITYIDEXTERNAL VARCHAR2(100), PIDFACILITYIDINTERNAL VARCHAR2(100), PIDFIRSTNAME VARCHAR2(100), PIDHOMEPHONE VARCHAR2(50),
    PIDLASTNAME VARCHAR2(100), PIDMEDICAIDNUMBER VARCHAR2(50), PIDMEDICALRECORDNUMBER VARCHAR2(100), PIDMIDDLENAME VARCHAR2(100), PIDMPI VARCHAR2(50), PIDNAMESUFFIX VARCHAR2(20),
    PIDNYSID VARCHAR2(50), PIDPATIENTACCOUNTNUM VARCHAR2(100), PIDPATIENTIDEXTERNAL VARCHAR2(100), PIDPATIENTIDINTERNAL VARCHAR2(100), PIDRACECODERAW VARCHAR2(100), PIDSEXCODE VARCHAR2(10),
    PIDSSN VARCHAR2(20), PIDSTATE VARCHAR2(50), PIDTYPEOFINSURANCE VARCHAR2(50), PIDVACCINETRIALIND VARCHAR2(10), PIDZIPCODE VARCHAR2(20), MSHCREATEDATE DATE, PIDDEATHDATE VARCHAR2(50),
    PIDDEATHIND VARCHAR2(10), MSHMESSAGECONTROLID VARCHAR2(100), MSHMESSAGEDATERAW VARCHAR2(50), MSHMESSAGETYPE VARCHAR2(50), PIDPATIENTIDLIST VARCHAR2(1000), PV1PROVIDERFIRSTNAME VARCHAR2(100),
    PV1PROVIDERLASTNAME VARCHAR2(100), PV1PROVIDERAUTH VARCHAR2(100), PV1ATTENDINGPROVIDERLIST VARCHAR2(1000), PIDRACECODESYSTEM VARCHAR2(100), MSHSENDINGFACILITYCODESYSTEM VARCHAR2(100),
    PIDVETERANSTATUS VARCHAR2(10), PIDWORKPHONE VARCHAR2(50), UPHN_TRANX_IN_ID NUMBER, PV1PROVIDERID VARCHAR2(100), PV1PROVIDERMIDDLENAME VARCHAR2(100), MSHMESSAGECLASS VARCHAR2(50),
    EVNEVENTTYPE VARCHAR2(50), EVNEVENTDATE VARCHAR2(50), PV1REFERRINGPROVIDERLIST VARCHAR2(1000), SEGMENTPROFILE VARCHAR2(1000), RACECODEDESC VARCHAR2(200), PIDNOTE VARCHAR2(2000),
    CCD_MATCH_DOC_ID NUMBER);
